package com.holidayhomemanager.app;
import android.app.Activity;import android.content.Intent;import android.net.Uri;import android.provider.CalendarContract;import com.getcapacitor.*;import com.getcapacitor.annotation.*;import androidx.activity.result.ActivityResult;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;
@CapacitorPlugin(name="Archive", permissions={@Permission(alias="notifications",strings={"android.permission.POST_NOTIFICATIONS"})}) public class ArchivePlugin extends Plugin {
@PluginMethod public void exportBackup(PluginCall call){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType(call.getString("mime","application/json"));i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,call.getString("filename","HolidayHomeManager.json"));startActivityForResult(call,i,"exported");}
@ActivityCallback private void exported(PluginCall call,ActivityResult r){if(call==null)return;if(r.getResultCode()!=Activity.RESULT_OK){JSObject cancelled=new JSObject();cancelled.put("cancelled",true);call.resolve(cancelled);return;}try{Uri u=r.getData().getData();try(OutputStream out=getContext().getContentResolver().openOutputStream(u,"wt")){if(out==null)throw new IOException("File non accessibile");out.write(call.getString("data","").getBytes(StandardCharsets.UTF_8));}call.resolve();}catch(Exception e){call.reject(e.toString());}}
@PluginMethod public void importBackup(PluginCall call){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(call,i,"imported");}
@ActivityCallback private void imported(PluginCall call,ActivityResult r){if(call==null)return;if(r.getResultCode()!=Activity.RESULT_OK){JSObject cancelled=new JSObject();cancelled.put("cancelled",true);call.resolve(cancelled);return;}try{Uri u=r.getData().getData();try(InputStream in=getContext().getContentResolver().openInputStream(u);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException("File non accessibile");byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>20*1024*1024)throw new IOException("Backup troppo grande");out.write(buf,0,n);}JSObject o=new JSObject();o.put("data",new String(out.toByteArray(),StandardCharsets.UTF_8));call.resolve(o);}}catch(Exception e){call.reject(e.toString());}}
@PluginMethod public void select(PluginCall call){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(call,i,"selected");}
@ActivityCallback private void selected(PluginCall call,ActivityResult result){if(call==null)return;if(result.getResultCode()!=Activity.RESULT_OK){call.reject("Selezione annullata");return;}try{Uri u=result.getData().getData();getContext().getContentResolver().takePersistableUriPermission(u,result.getData().getFlags()&3);String s;try(InputStream in=getContext().getContentResolver().openInputStream(u)){s=new String(in.readAllBytes(),StandardCharsets.UTF_8);}getContext().getSharedPreferences("archive",0).edit().putString("uri",u.toString()).apply();JSObject o=new JSObject();o.put("data",s);call.resolve(o);}catch(Exception e){call.reject(e.toString());}}
@PluginMethod public void create(PluginCall call){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"HolidayHomeManager.json");startActivityForResult(call,i,"created");}
@ActivityCallback private void created(PluginCall call,ActivityResult r){if(call==null)return;if(r.getResultCode()!=Activity.RESULT_OK){call.reject("Annullato");return;}try{Uri u=r.getData().getData();getContext().getContentResolver().takePersistableUriPermission(u,r.getData().getFlags()&3);getContext().getSharedPreferences("archive",0).edit().putString("uri",u.toString()).apply();write(call);}catch(Exception e){call.reject(e.toString());}}
@PluginMethod public synchronized void write(PluginCall call){try{String s=getContext().getSharedPreferences("archive",0).getString("uri",null);if(s==null){call.reject("Archivio non configurato");return;}try(OutputStream out=getContext().getContentResolver().openOutputStream(Uri.parse(s),"wt")){out.write(call.getString("data","").getBytes(StandardCharsets.UTF_8));}call.resolve();}catch(Exception e){call.reject(e.toString());}}
@PluginMethod public void calendar(PluginCall call){try{long start=LocalDateTime.parse(call.getString("date")+"T"+call.getString("time")).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();Intent i=new Intent(Intent.ACTION_INSERT).setData(CalendarContract.Events.CONTENT_URI).putExtra(CalendarContract.Events.TITLE,call.getString("title")).putExtra(CalendarContract.EXTRA_EVENT_BEGIN_TIME,start).putExtra(CalendarContract.EXTRA_EVENT_END_TIME,start+1800000);getActivity().startActivity(i);call.resolve();}catch(Exception e){call.reject(e.toString());}}
@PluginMethod public void reminders(PluginCall call){if(android.os.Build.VERSION.SDK_INT>=33&&getPermissionState("notifications")!=PermissionState.GRANTED){requestPermissionForAlias("notifications",call,"reminderPermission");return;}applyReminders(call);}
@PermissionCallback private void reminderPermission(PluginCall call){if(getPermissionState("notifications")!=PermissionState.GRANTED){call.reject("Permesso notifiche negato");return;}applyReminders(call);}
private void applyReminders(PluginCall call){try{android.app.AlarmManager am=(android.app.AlarmManager)getContext().getSystemService(android.content.Context.ALARM_SERVICE);android.content.SharedPreferences prefs=getContext().getSharedPreferences("reminders",0);for(String id:prefs.getStringSet("ids",new java.util.HashSet<String>())){android.app.PendingIntent pi=reminderIntent(id,"");am.cancel(pi);pi.cancel();}java.util.HashSet<String> ids=new java.util.HashSet<>();org.json.JSONArray rows=call.getArray("events");for(int i=0;i<rows.length();i++){org.json.JSONObject row=rows.getJSONObject(i);String id=row.getString("id");long at=row.getLong("at");if(at<=System.currentTimeMillis())continue;am.setAndAllowWhileIdle(android.app.AlarmManager.RTC_WAKEUP,at,reminderIntent(id,row.getString("title")));ids.add(id);}prefs.edit().putStringSet("ids",ids).apply();JSObject result=new JSObject();result.put("count",ids.size());call.resolve(result);}catch(Exception e){call.reject(e.toString());}}
private android.app.PendingIntent reminderIntent(String id,String title){Intent i=new Intent(getContext(),ReminderReceiver.class).setData(Uri.parse("hhm://reminder/"+id)).putExtra("title",title);return android.app.PendingIntent.getBroadcast(getContext(),0,i,android.app.PendingIntent.FLAG_UPDATE_CURRENT|android.app.PendingIntent.FLAG_IMMUTABLE);}
}